/* Each entry owns its explanation and experiment; caching policy is not a decorative toggle. */
const SD_CACHE_CONTENT={
 'why-caching-exists':{
  hook:'Do the expensive work once.',caption:'Repeat a request and watch which source operations disappear.',
  intro:['A repeated book lookup can ask the same source for the same representation again and again. A cache retains a reusable copy so later requests can avoid selected work. The motivation is latency and resource use, not the belief that another box automatically makes an architecture better.'],
  fundamentals:['A hit finds an eligible stored value; a miss cannot use an entry and needs another path. The source of truth owns the authoritative fact. A cache usually stores a copy with a key and a reuse policy. Hit ratio describes lookups, while source-read count describes downstream work; disabling cache creates no cache lookups rather than a stream of misses.'],
  deep:['Caching is valuable when repeated accesses reuse work and the reuse policy meets correctness requirements. It can retain representations, computed results, or storage pages, which avoid different work. A fresh-looking copy can still be older than the source. Keys must include the dimensions that affect the result, such as tenant, locale, and relevant authorization context; an incomplete key can return another caller’s representation.','Caches add lookup overhead, memory use, invalidation obligations, and failure paths. A low-reuse workload may cost more with caching, and a cache outage can suddenly shift load to the source. This model repeats one small public book value with illustrative times. It does not establish a production latency distribution or imply that every private response can safely be shared.'],
  working:['Read the key before any copy exists.','Fetch source v1 and retain it under the selected TTL.','Repeat the request and compare hit count with source reads.','Disable reuse and observe repeated source work without inventing cache misses.'],
  usage:['A public catalog description can often be reused under a documented freshness policy. A checkout reservation still needs an authoritative update path.','Measure repeated access, avoided work, hit ratio, and correctness together; a high hit ratio is not evidence that the returned values meet the application’s promise.'],
  summary:['A cache reuses selected work.','A copy and the source of truth remain separate.','Correct reuse needs a complete key and a freshness policy.'],check:['Does a high hit ratio prove every response is current?','No. The cache can repeatedly hit an older copy. The metric measures eligible lookup success, not agreement with the latest source.'],
  controls:[['requests','Repeated requests',1,4,3],['enabled','Enable cached reuse','checkbox',true],['latency','Source read (model ms)',20,200,90]],presets:[['Cold then warm',{requests:3,enabled:true}],['Always source',{requests:3,enabled:false}]],
  glossary:{Hit:'A lookup satisfied by an eligible stored entry.',Miss:'A lookup without an eligible reusable entry.','Source of truth':'The authoritative owner of a fact.'},sources:[['Azure cache-aside pattern','https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside']]
 },
 'browser-caching':{
  hook:'No network, validation, or a new body?',caption:'Inspect freshness, ETags, 304 responses, and storage policy separately.',
  intro:['Reloading an image does not always transfer its bytes again. An HTTP cache can reuse a fresh response or ask the origin whether an old representation remains valid. Those are different paths, and neither can be understood from a generic browser-to-server arrow.'],
  fundamentals:['Cache-Control defines reuse rules. max-age permits freshness for a stated duration under HTTP age calculation. no-cache allows storage but requires validation before reuse; no-store tells caches not to store the response. An ETag is an opaque validator. If-None-Match sends it for comparison, and 304 permits reuse of a stored representation without resending its full body.'],
  deep:['Freshness is not a promise that the origin has not changed. A browser can reuse a fresh body without asking, so an unseen update can remain unseen until policy requires a network path. Validation can save payload bytes while still adding round-trip work. Real age calculations include Date, Age, and resident time; the lab deliberately uses a simple model clock for one browser cache.','Shared caches require additional care with private data, Authorization, Vary, and request dimensions. private limits shared-cache storage but is not encryption. no-store is not a complete security cleanup mechanism and does not guarantee removal of previously stored responses. The lab models a public image, a single strong-looking fake ETag, and one conditional request, not every HTTP caching rule or service worker behavior.'],
  working:['Receive body v1 and its caching policy.','Advance model age and optionally change the origin.','Reuse a fresh body locally or perform the required validation.','Compare network-request count with full-body transfers for 304 and 200 outcomes.'],
  usage:['Versioned static assets can use long-lived reuse when a changed asset gets a new URL. Personalized pages need explicit private and storage rules.','Treat a 304 as useful network work, not an absence of a request. Later CDN lessons add a shared cache boundary with its own key and age behavior.'],
  summary:['Fresh reuse and validation are distinct paths.','no-cache and no-store mean different things.','304 saves the full-body transfer, not the round trip.'],check:['Can no-cache still store a response?','Yes. It requires validation before reuse. no-store is the policy prohibiting storage for this modeled response.'],
  controls:[['policy','Cache-Control policy','select',['max-age','no-cache','no-store'],'max-age'],['maxAge','Fresh lifetime (seconds)',10,90,30],['age','Next request age (seconds)',0,120,10],['changed','Origin changed to v2','checkbox',false]],presets:[['Fresh local reuse',{policy:'max-age',age:10,changed:true}],['Validate unchanged',{policy:'no-cache',age:10,changed:false}],['Changed validator',{policy:'no-cache',age:10,changed:true}],['Do not store',{policy:'no-store',age:10}]],
  glossary:{ETag:'An opaque representation validator.',Validation:'Checking whether a stored response can be reused.',Freshness:'Eligibility to reuse without required origin validation under the policy.'},sources:[['MDN HTTP caching','https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching'],['HTTP caching RFC 9111','https://www.rfc-editor.org/rfc/rfc9111.html']]
 },
 'application-caching':{
  hook:'The next worker may remember something else.',caption:'Compare process-local copies with a shared cache boundary.',
  intro:['Application code can retain a calculated value or fetched record inside its own process. That can avoid a remote lookup, but another worker has separate memory. Restart and replica routing therefore change which copy is available.'],
  fundamentals:['A process-local cache belongs to one worker. A shared cache is an external dependency reachable by several workers. Neither automatically updates when source data changes. The lab loads a copy on A, changes the source, and reads through B; warming B creates another independently retained local value.'],
  deep:['Local reuse can have low access overhead and avoid a separate cache service, but it duplicates memory and complicates coordinated invalidation. Invalidating A does not remove B’s independent copy. Keys, capacity limits, expiry, and concurrent-load handling still need design. A process restart normally loses local entries, which is harmless only if they are reconstructible copies rather than indispensable authoritative state.','Shared caches reduce some duplication but add network latency and an availability boundary. Combining local and shared layers creates more freshness paths, not a magically current result. The lab uses two workers and a single public key without restart scheduling or broadcasting. It isolates state placement; it does not implement a multi-level cache coherence protocol or claim every local cache needs external infrastructure.'],
  working:['Warm A and optionally warm B with v1.','Change the authoritative source to v2.','Invalidate the copy known to A if selected.','Read on B and distinguish independent local state from the shared entry.'],
  usage:['A worker can memoize a small immutable configuration or public lookup under an explicit lifetime. Mutable user-specific results require complete keys and update rules.','Keep local-cache memory bounded and monitor misses after replacement or restart. Plan source capacity for cold starts rather than assuming every new worker arrives warm.'],
  summary:['Worker memory is not automatically shared.','Local invalidation affects only the copies it reaches.','Reconstructible cached state differs from authoritative state.'],check:['Does removing A’s local entry remove B’s warm copy?','No. Those are independent process-local values unless a separate coordination mechanism updates B.'],
  controls:[['location','Cache location','select',['local','shared'],'local'],['warmB','Warm B before source update','checkbox',false],['invalidate','Invalidate A’s known entry','checkbox',false]],presets:[['B starts cold',{location:'local',warmB:false,invalidate:false}],['B retains old copy',{location:'local',warmB:true,invalidate:true}],['Shared removal',{location:'shared',invalidate:true}]],
  glossary:{'Local cache':'Reusable data retained inside an individual process.','Cold start':'Beginning work without populated reusable state.',Memoization:'Retaining a function result for compatible future inputs.'},sources:[['Azure cache-aside considerations','https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside']]
 },
 'database-caching':{
  hook:'A cached page is not a cached query result.',caption:'Run the query again while its data page stays resident.',
  intro:['A database can avoid storage reads without skipping the query. Buffer pools retain pages used by the execution engine. This is a different layer from an application cache returning a previously computed representation.'],
  fundamentals:['A database page groups stored records or index data. A buffer hit finds the requested page resident in memory. The executor still applies visibility rules and predicates to those bytes. The lab tracks query executions and modeled storage reads separately; its database actor also represents the underlying storage path for this simplified scene.'],
  deep:['Page residency affects I/O, but transactions can require readers to consider different visible versions. Reusing page bytes is not permission to return another transaction’s stale SQL result. Database engines have replacement, pinning, dirty-page flushing, and synchronization policies; an application-result TTL is not a substitute for those rules. OS page caches can provide another layer outside the database buffer pool.','A warm query can still be slow because it sorts, joins, waits on locks, or returns a large result. Query-result caches, when a product provides them, need their own dependency and invalidation semantics. This experiment uses one repeated page and one simple predicate. It deliberately does not reproduce PostgreSQL’s buffer replacement policy, storage concurrency, or every available database cache feature.'],
  working:['Execute the first query and request its page.','Perform a modeled cold storage read.','Execute later queries and reuse the resident page.','Disable residency and compare unchanged execution count with increased storage reads.'],
  usage:['A frequently used index and table working set can remain resident while the database executes many requests. A large export may displace useful pages or use specialized access behavior.','Inspect buffer and query observations together. Stage 3’s access-path experiment explains why saving physical reads does not remove logical row evaluation.'],
  summary:['Page caching avoids selected storage work.','Queries still execute on resident pages.','Result caches and buffer pools have different semantics.'],check:['Three warm SELECTs access one page. Must the executor run only once?','No. Each SELECT executes. The model reduces storage reads to one while retaining three query executions.'],
  controls:[['requests','Query executions',1,4,3],['enabled','Retain page in buffer pool','checkbox',true],['latency','Cold storage read (model ms)',20,200,90]],presets:[['Resident working page',{requests:3,enabled:true}],['Cold each time',{requests:3,enabled:false}]],
  glossary:{'Buffer hit':'A requested database page found in memory.',Visibility:'The transaction rules determining readable versions.','Result cache':'Retained output of a query, rather than just its storage pages.'},sources:[['PostgreSQL EXPLAIN buffer observations','https://www.postgresql.org/docs/current/using-explain.html']]
 },
 'distributed-caching':{
  hook:'Shared does not mean current.',caption:'Two workers can reach one cache—and one older copy.',
  intro:['Several application workers can use an external cache service to share reusable values. This can reduce repeated source loads, but shared access does not mean the value is the newest authoritative one. Freshness still needs an update policy.'],
  fundamentals:['A distributed cache is accessed across process or network boundaries and may partition or replicate its own data. The lab intentionally models one shared cache endpoint, not a full cluster. Workers use the same key; after a source update, their next eligible lookup can still return v1 unless the entry is removed or updated.'],
  deep:['A cache cluster needs documented routing, failover, replication, eviction, and consistency behavior. A timeout can mean uncertain command completion, and a replica read may introduce additional lag. Shared storage solves process-local access differences but does not eliminate version races. Tenant and representation dimensions must remain in the key even when one service handles all workers.','An external cache becomes a dependency with network cost and outage behavior. It should not silently become the sole holder of critical writes unless that durability role is deliberately designed. This diagram shows two workers and one shared entry to isolate reuse and invalidation. It does not simulate Redis Cluster slot migration or claim that every distributed cache is strongly consistent, durable, or automatically available.'],
  working:['Populate the shared value as v1.','Commit source v2 independently.','Optionally remove the shared copy after the write.','Read through B and compare stale shared reuse with a refreshed miss path.'],
  usage:['A horizontally scaled public catalog can share repeated representations across workers. Checkout policies still need authoritative data paths for invariants.','Choose a fallback policy and budget source capacity for cache loss. A shared endpoint can multiply usefulness and the impact of mistakes, especially incomplete keys or broad invalidations.'],
  summary:['Shared reuse is a placement property.','Freshness depends on a separate policy.','The cache service adds a network failure boundary.'],check:['Can two healthy workers agree on the same stale value?','Yes. Both can hit the same shared v1 entry after the source moves to v2. Agreement among copies does not prove source freshness.'],
  controls:[['invalidate','Remove shared entry after source write','checkbox',false]],presets:[['Shared but older',{invalidate:false}],['Shared invalidation',{invalidate:true}]],
  glossary:{'Shared entry':'A stored value reachable by several workers.','Cache cluster':'Cache nodes coordinated for placement or availability.',Freshness:'How a returned copy relates to required source updates.'},sources:[['Azure cache-aside pattern','https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside'],['Redis cluster specification','https://redis.io/docs/latest/operate/oss_and_stack/reference/cluster-spec/']]
 },
 'cache-aside':{
  hook:'The application owns the miss path.',caption:'Follow lookup, source fetch, fill, and later reuse.',
  intro:['A cache-aside application checks for a reusable copy and explicitly fetches from the source when it misses. The cache does not know how to load the value on its own. This division of responsibility matters when work fails or requests race.'],
  fundamentals:['The common read sequence is lookup, miss, source load, cache fill, and response. A write policy often commits the source and removes the related cached entry. Filling the cache is a separate action from returning an authoritative read; it should be clear whether a fill error fails an otherwise successful operation.'],
  deep:['Two readers can miss together and both load the same source value unless requests are coalesced. A reader can also load an older value, pause, and fill it after a writer commits and invalidates, recreating stale data. Choosing source-then-delete avoids some simpler write-ordering hazards but does not eliminate every concurrent refill race; the invalidation lesson demonstrates that counterexample.','Define TTLs, key granularity, fill failure behavior, invalidation delivery, and fallback before relying on the pattern. A TTL bounds this stored entry’s eligibility but is not a universal latest-read guarantee. This serial read lab isolates cache-aside responsibility and its ledger supports explicit subsequent operations. It is not a coherent cache protocol or an assurance that repeating a database read is always safe or cheap.'],
  working:['Ask the cache for book:atlas.','On a miss, let the application fetch the source.','Let the application store the copy and return the value.','Repeat, change source state, or remove the entry and observe the next path.'],
  usage:['A catalog handler can load a reconstructible description on demand. It should avoid storing mutable permission-dependent results under a public shared key.','Cache-aside is often easy to add around an existing source interface, but its coordination responsibilities remain in the application rather than disappearing into the cache box.'],
  summary:['The application owns loading and fill.','Source writes and copy removal are distinct.','Concurrent readers can create duplicate loads or late fills.'],check:['Does an ordinary cache-aside cache fetch from the database by itself?','No. The application handles the miss and writes the reusable copy. Read-through assigns that loading responsibility to a configured facade or loader.'],
  controls:[['requests','Read requests',1,4,2],['ttl','Copy lifetime (seconds)',5,60,30],['invalidate','Invalidate after live source writes','checkbox',true]],presets:[['Miss then hit',{requests:2,ttl:30,invalidate:true}],['Single cold request',{requests:1,ttl:30,invalidate:true}]],
  glossary:{'Cache-aside':'Application-managed lookup, source loading, and fill.',Fill:'Storing a fetched value for later reuse.',Coalescing:'Sharing one in-flight load among compatible callers.'},sources:[['Azure cache-aside','https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside']]
 },
 'read-through-and-write-through':{
  hook:'Who loads? Who acknowledges the write?',caption:'Open the cache facade’s loader and synchronous persistence boundary.',
  intro:['An application can ask a configured cache facade to load missing values rather than implement the miss path itself. Write-through can likewise coordinate source persistence before reporting write success. These are responsibilities, not automatic features of every key-value cache.'],
  fundamentals:['Read-through assigns miss loading to a facade or loader. Write-through updates the backing source as part of the acknowledged write path. Cache-aside instead asks application code to coordinate loading and filling. The lab shows a specific serialized facade policy and keeps its success acknowledgement separate from accepting a command.'],
  deep:['A write-through path needs documented ordering and failure behavior. If the source succeeds but a cache update fails, the system must decide how to invalidate, report uncertainty, or recover without leaving an apparently authoritative old copy. A cache and remote database are not automatically one atomic transaction because a library exposes a convenient interface.','Synchronous persistence adds waiting time and can reduce acknowledged-write risk under a defined policy, but it does not guarantee every concurrent read is newest. Loader stampedes, bypassing writers, version races, and facade outages remain concerns. This lab models source failure before persistence and keeps the old value on rejection. It deliberately does not claim to solve failures between a successful source commit and a failed cache update.'],
  working:['Ask the facade for an initially absent key.','Invoke its configured loader and store source v1.','Send write-through v2 and wait for persistence.','Compare successful source and copy updates with a rejected persistence failure.'],
  usage:['A controlled data-access layer can centralize loading and write policy for callers that consistently use it. Writers bypassing that layer still need coordination.','Document which failures return success, failure, or uncertainty. A single write method name does not establish an atomic boundary across separate services.'],
  summary:['Read-through owns loading at the facade.','Write-through includes persistence before success.','Cross-service atomicity needs more than an interface name.'],check:['Is storing v2 in memory sufficient for this write-through success response?','No. This facade waits for its backing-source operation and cache update before acknowledging success.'],
  controls:[['fail','Fail backing persistence','checkbox',false],['latency','Source operation (model ms)',20,200,90]],presets:[['Write accepted',{fail:false}],['Backing write rejected',{fail:true}]],
  glossary:{Facade:'A boundary presenting a coordinated interface.',Loader:'Code supplying a missing cached value.','Write-through':'A write policy including backing persistence before success.'},sources:[['Oracle Coherence source-caching patterns','https://docs.oracle.com/en/middleware/fusion-middleware/coherence/14.1.2/develop-applications/caching-data-sources.html']]
 },
 'write-behind':{
  hook:'Success now. Persistence later.',caption:'Inspect the pending write queue before crashing its process.',
  intro:['Some designs acknowledge a cached write before applying it to the backing source. This can shorten the caller’s wait and combine later writes, but it moves correctness obligations into a pending-work pipeline. The older source value is still real until that pipeline applies the change.'],
  fundamentals:['Write-behind, also called write-back in some contexts, defers source persistence. A pending queue owns accepted but unapplied changes. A volatile queue disappears with its process; a durable queue can retain work under specified storage and failure assumptions. Early acknowledgement is not the same event as backing-store completion.'],
  deep:['Accepted writes need ordering, deduplication, retry, backpressure, and recovery rules. Combining writes can be safe for some replacement values but wrong for operations where every increment or transition matters. Losing a volatile queue after early success can lose acknowledged data even while the old source remains intact. A durable queue must itself provide the promised persistence and replay semantics.','Deferred work can fail after the original request ends, so monitoring must detect stalled or repeatedly rejected updates and expose an operational recovery path. Readers consulting the source may see older data until flush. This experiment contains one versioned update, an optional process crash, and a simplified durable-queue assumption. It does not reproduce a production broker or assert atomicity between cache acceptance and queue persistence.'],
  working:['Accept cache v2 and retain a pending update.','Acknowledge before changing source v1.','Crash the cache process and inspect whether pending work survives.','Flush retained work or leave it unapplied and compare the persistent source.'],
  usage:['A carefully defined high-volume derived-data pipeline may tolerate delayed persistence and benefit from coalescing. A critical ledger should not casually adopt volatile write-behind for accepted facts.','State the durability role explicitly. If the cache is holding the only accepted value, it is participating in authoritative storage responsibilities rather than merely saving a reconstructible read.'],
  summary:['Acknowledgement and persistence have different times.','Pending accepted work needs a recovery policy.','Volatile write-behind can lose acknowledged changes.'],check:['After a volatile queue crash, can flushing an empty queue recover v2?','No. The accepted pending update was lost. The source still contains v1 unless another retained record can reconstruct the change.'],
  controls:[['crash','Crash before flush','checkbox',false],['durable','Pending queue survives process crash','checkbox',false],['flush','Flush retained work','checkbox',true]],presets:[['Deferred success',{crash:false,durable:false,flush:true}],['Acknowledged loss',{crash:true,durable:false,flush:true}],['Retained pending work',{crash:true,durable:true,flush:true}]],
  glossary:{'Write-behind':'Acknowledging before later backing persistence.','Pending work':'Accepted updates not yet applied to the source.',Backpressure:'Restraining incoming work when processing cannot keep up.'},sources:[['Oracle Coherence deferred persistence','https://docs.oracle.com/en/middleware/fusion-middleware/coherence/14.1.2/develop-applications/caching-data-sources.html']]
 },
 'ttl':{
  hook:'The clock expires eligibility—not truth.',caption:'Advance time explicitly and distinguish a valid old copy from an expired entry.',
  intro:['A cache cannot usually keep every copied value forever. A time to live defines how long an entry remains eligible under a policy. Expiry encourages later refresh, but it does not make the copy track every source change in between.'],
  fundamentals:['TTL is a remaining lifetime or insertion-relative expiry policy, depending on the interface. Our copy expires at insertion time plus the selected seconds. Reads do not refresh that deadline. The ledger can show an expired stored value before a lookup removes it; physical reclamation and eligibility are separate concepts.'],
  deep:['A TTL can bound reuse of a particular copy but is not by itself a strict maximum lag from every source commit. Delayed fills can install old values later, and source replicas can return stale values. Different systems reset TTL on writes, expose explicit persistence operations, or support sliding policies; none should be assumed without checking the interface.','Short lifetimes increase refresh load, while long ones permit longer stale reuse. Identical expiry times can concentrate misses into a burst, so jitter and refresh coordination may help. Negative entries need carefully chosen lifetimes too. This lab uses one key, insertion-relative expiry, and explicit model-clock changes; it does not simulate Redis’s full active-expiry scheduler or real wall-clock drift.'],
  working:['Insert a copy and record its expiry.','Advance between repeated requests.','Reuse before expiry and reload at or after the deadline.','Change source data during a live session and compare eligibility with source agreement.'],
  usage:['A public catalog description may accept bounded reuse under a freshness requirement. Security revocation or inventory reservation needs more specific correctness mechanisms than a casually selected TTL.','Tune lifetime against observed reuse and tolerated staleness, and account for the source load created when many entries expire together.'],
  summary:['TTL controls entry eligibility.','Expiry and physical deletion can be separate.','TTL alone does not prove latest-source consistency.'],check:['If an entry has five seconds left, must it equal the newest source version?','No. It can remain eligible while the source changes independently. The live source-write action demonstrates that distinction.'],
  controls:[['ttl','Entry lifetime (seconds)',5,60,30],['interval','Between requests (seconds)',5,40,15],['requests','Read requests',1,4,3]],presets:[['Hit before deadline',{ttl:30,interval:10,requests:3}],['Expire at boundary',{ttl:30,interval:15,requests:3}],['Frequent reload',{ttl:5,interval:15,requests:3}]],
  glossary:{TTL:'A policy-defined remaining entry lifetime.',Expiry:'The point after which this entry cannot satisfy reuse.',Jitter:'Varying timings to avoid synchronized events.'},sources:[['Redis EXPIRE','https://redis.io/docs/latest/commands/expire/']]
 },
 'cache-eviction-strategies':{
  hook:'Full cache. Which value leaves?',caption:'Replay a workload and inspect recency, frequency, and admission.',
  intro:['Even entries that have not expired may need removal when memory is full. An eviction strategy chooses which values to sacrifice so later work can enter. That decision depends on workload behavior, not merely on the number of stored keys.'],
  fundamentals:['LRU removes the least recently used entry. LFU favors keeping more frequently used entries. FIFO removes the oldest admitted entry regardless of later reads. Expiry removes time-ineligible entries; eviction addresses capacity pressure. The lab gives equal-sized values a key-count capacity and exact policy bookkeeping.'],
  deep:['Real entry sizes vary, and storing a key uses metadata as well as value bytes. Admission can matter as much as eviction: a large one-time scan may displace useful hot data. LFU needs aging or another adaptation rule when popularity changes; pure lifetime counts can retain a formerly hot entry too long. The deterministic trace allows ties to be inspected rather than hidden behind randomness.','Redis uses approximated sampling-based policies for LRU and LFU rather than this exact tiny implementation; its memory configuration and eligible-key policies also matter. noeviction rejects selected writes instead of inventing infinite space. This lesson compares exact LRU, LFU with recency tie-breaking, and FIFO for six accesses. It is not a performance ranking of Redis policies or a realistic allocator simulation.'],
  working:['Replay the chosen six-key access sequence.','Update recency and frequency on hits.','When a miss meets a full cache, select the policy’s victim.','Load the requested value and compare final residents, hits, and source reads.'],
  usage:['A public lookup workload with a recurring hot set behaves differently from a one-time report scanning many keys. Select policies and admission around representative access traces.','Monitor both evictions and expirations. A low hit ratio can arise from a poor key, too little memory, a short TTL, or low inherent reuse; changing eviction alone may not solve it.'],
  summary:['Capacity eviction differs from expiry.','Recency, frequency, and insertion age are different signals.','Exact teaching policies differ from real approximations.'],check:['Does reading a FIFO entry move it to the back of the insertion order?','No in this exact FIFO model. LRU updates recency; FIFO keeps the original admission order.'],
  controls:[['policy','Exact teaching policy','select',['LRU','LFU','FIFO'],'LRU'],['capacity','Equal-size entry slots',2,4,3],['sequence','Access workload','select',['hot','scan'],'hot']],presets:[['Recency policy',{policy:'LRU',capacity:3,sequence:'hot'}],['Frequency policy',{policy:'LFU',capacity:3,sequence:'hot'}],['Insertion order',{policy:'FIFO',capacity:3,sequence:'hot'}]],
  glossary:{LRU:'Least recently used eviction.',LFU:'Least frequently used eviction.',FIFO:'First-in, first-out removal by admission age.'},sources:[['Redis eviction policies and approximations','https://redis.io/docs/latest/develop/reference/eviction/']]
 },
 'cache-invalidation':{
  hook:'Delete the copy. A late reader puts it back.',caption:'Interleave a miss loader and writer to expose a refill race.',
  intro:['Removing a cached value after a source write seems straightforward. But a reader may already have fetched the old source value and publish it after the deletion. A real invalidation design must consider work in flight, not just the current cache contents.'],
  fundamentals:['Invalidation makes a copy ineligible, commonly by deleting or changing its key. A late fill is a load result published after intervening updates. Our schedule loads v1, commits v2, optionally deletes the key, and then lets the old reader try to cache its result.'],
  deep:['Source-then-delete can address some simple ordering problems, but it does not eliminate this concurrent refill schedule. Deleting before writing introduces another obvious gap where readers can refill from the old source. Delayed deletion or events can reduce specific risks, yet need failure and timing analysis instead of being described as universal coherence.','A conceptual generation guard rejects a fill started under an older generation. Production correctness requires a coordinated token protocol across checking, publishing, writes, and readers; merely comparing a number once is not enough if a write can race afterward. Versioned keys and reliable change streams are other tools with their own costs. This deterministic schedule illustrates one race and one abstract guard, not a complete linearizable cache implementation.'],
  working:['Start a miss reader and retain its fetched v1 in flight.','Commit source v2.','Delete the cached entry if selected.','Allow or reject the late fill, then read and inspect the actual returned version.'],
  usage:['A mutable catalog can see this race when slow source reads overlap editorial updates. A stale title may be tolerable; a stale permission decision can be dangerous.','Choose invalidation granularity and freshness promises explicitly. The cache-consistency lesson connects those update protocols to what callers may observe.'],
  summary:['Invalidation does not cancel in-flight loads.','Write ordering needs concurrency analysis.','A guard must be coordinated to establish its promised guarantee.'],check:['Why can source-then-delete still leave v1 after source v2 commits?','An earlier reader fetched v1 before the write, then fills the cache after the deletion. The deletion cannot erase a value that has not yet been published.'],
  controls:[['invalidate','Delete after source commit','checkbox',true],['guard','Conceptual generation guard','checkbox',false],['ttl','Filled copy lifetime (seconds)',5,60,30]],presets:[['Late refill race',{invalidate:true,guard:false}],['No deletion',{invalidate:false,guard:false}],['Reject older generation',{invalidate:true,guard:true}]],
  glossary:{Invalidation:'Making a cached copy ineligible.',Generation:'A token identifying an update epoch.','Late fill':'Publishing an earlier load result after a newer write.'},sources:[['Azure cache-aside consistency considerations','https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside']]
 },
 'cache-consistency':{
  hook:'Which version does this reader observe?',caption:'Separate source commit, copy validity, and a completed response.',
  intro:['A cache is a second place from which callers can observe data. The application needs a clear promise about those observations: latest value, session read-after-write, bounded reuse, or an explicitly eventual projection. Without that promise, “consistent cache” is too vague to assess.'],
  fundamentals:['A source commit changes authoritative state. A cached value can remain eligible yet older. Read-after-write is a session-level expectation that a later read reflects that session’s accepted write under defined conditions. The late-fill schedule here shows why a source commit and key deletion do not automatically establish that expectation.'],
  deep:['Consistency depends on the complete read and write protocol, including writers that bypass the cache, replicas used for fills, and failures delivering invalidations. Routing to the source, version-aware reads, generation barriers, or explicit wait conditions can address particular promises with different latency and availability costs. A single TTL knob cannot stand in for all those mechanisms.','The generation guard is an abstract coordinated policy that rejects this older fill; it is not a production recipe proving all races safe. A stale value already returned remains an observation even if the cache later converges. This lab keeps returned versions in its ledger so convergence is not mistaken for retroactive correctness. It does not model every consistency level or a complete multi-node cache protocol.'],
  working:['Capture an older source value during a miss load.','Commit a newer source value.','Apply deletion and the optional guarded-fill policy.','Read the cache path and compare the returned version with the source, preserving earlier observations.'],
  usage:['A public description can often tolerate documented stale reuse, while account revocation or a purchase invariant needs a stronger path. Different endpoints can have different promises.','Describe the user-visible guarantee before choosing a cache topology. Shared storage, replication, and fast responses are not themselves a definition of consistency.'],
  summary:['State the observation guarantee.','TTL-valid can still mean source-stale.','Later convergence does not fix an earlier returned response.'],check:['After the cache catches up, was a previously returned v1 actually v2?','No. That caller observed v1 at that time. Refresh changes future reads, not the content of an already-completed response.'],
  controls:[['invalidate','Invalidate after write','checkbox',true],['guard','Coordinated generation model','checkbox',false]],presets:[['Older observation',{invalidate:true,guard:false}],['Guarded fresh reload',{invalidate:true,guard:true}]],
  glossary:{'Read-after-write':'A defined promise for reads following a caller’s accepted write.',Convergence:'Copies moving toward the same state over time.','Stale observation':'A returned value older than the required source state.'},sources:[['Azure cache-aside consistency','https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside']]
 },
 'redis-fundamentals':{
  hook:'A command changes value—not every property.',caption:'Run SET with expiry, atomic INCR, and a later GET.',
  intro:['Redis exposes commands over typed values addressed by keys. It can serve caching roles, but its command semantics need to be understood before building policies around them. A key’s value, lifetime, persistence, and replication are separate concerns.'],
  fundamentals:['This command lab uses a string containing an integer. SET with EX assigns a value and expiry together. INCR atomically changes a valid numeric string and preserves an existing TTL. GET returns a string value or nil when the key is absent; nil is not the same as an empty string.'],
  deep:['Other Redis data types include hashes, lists, sets, sorted sets, and streams, each with their own operations. Command atomicity does not make a sequence of separate client commands atomic as a whole. Transactions and scripts have documented execution properties and cluster restrictions; a read followed by a separate write can still race with other clients.','Persistence and replication must be configured and understood rather than inferred from Redis storing data in memory. Expiry uses passive access checks and active work, while eviction handles memory pressure separately. The teaching clock has exact expiration boundaries and no real server or network. This lesson implements only the displayed SET, INCR, and GET schedule and does not pretend to provide a general Redis interpreter.'],
  working:['SET the fake key to numeric string 1 with EX.','INCR its value to 2 without extending the existing lifetime.','Advance model time explicitly.','GET the value before or at expiry and inspect string-versus-nil behavior.'],
  usage:['A cache can store a public representation with a lifetime, while a counter can use atomic increments. Whether the counter may be evicted or lost depends on its business meaning.','Avoid mixing indispensable facts with reconstructible cache entries under an indiscriminate eviction policy. Data role, command semantics, and durability need a consistent design.'],
  summary:['Redis values have types and command semantics.','INCR does not renew this existing TTL.','Memory, expiry, eviction, and durability are separate.'],check:['Does INCR extend the deadline established by SET EX in this model?','No. It changes the numeric value while preserving the existing expiry, matching the referenced command semantics.'],
  controls:[['ttl','SET EX lifetime (seconds)',5,60,30],['age','GET age (seconds)',0,90,10]],presets:[['GET numeric string',{ttl:30,age:10}],['GET after expiry',{ttl:30,age:30}]],
  glossary:{INCR:'An atomic increment of a numeric string value.',nil:'A missing value response, distinct from an empty string.',EX:'A SET option specifying expiry in seconds.'},sources:[['Redis INCR','https://redis.io/docs/latest/commands/incr/'],['Redis EXPIRE','https://redis.io/docs/latest/commands/expire/'],['Redis SET','https://redis.io/docs/latest/commands/set/']]
 },
 'cache-failure-scenarios':{
  hook:'The cache fails. The database feels it.',caption:'Compare cold-load stampedes, coalescing, and outage fallback.',
  intro:['A popular key can trigger many source requests when it is absent, expired, or inaccessible. The cache may have been hiding substantial load, so falling back to the database is not automatically safe. Failure policy is part of the architecture.'],
  fundamentals:['A stampede is a concentration of duplicate loads for the same missing value. Request coalescing shares one in-flight load among compatible callers. A cache outage is an unavailable dependency, not a valid miss response. The application can reject, degrade, or use a bounded fallback path according to its requirements.'],
  deep:['Coalescing needs a scope, key, timeout, error propagation, and cancellation policy. A single-process gate may still allow one duplicate load per worker, while a distributed coordination scheme adds its own failure cases. Backpressure, bounded source concurrency, jittered expiry, and controlled refresh can address different overload paths; none should be substituted for measuring the source’s safe capacity.','A fallback that sends every caller to an already-busy source can turn a cache incident into a wider outage. Failing closed preserves some resources but sacrifices availability. Serving stale can be appropriate only for endpoints whose correctness policy permits it. This experiment groups simultaneous callers to one public key and models exact coalescing; its source loads are counted, not a simulation of real concurrent latency or a production circuit breaker.'],
  working:['Generate a group of simultaneous requests for one cold key.','Choose ordinary miss or cache unreachability.','Reject or fall back, optionally sharing a single source load.','Compare source-load count, rejected callers, and response availability.'],
  usage:['A public catalog may safely degrade under cache loss, but an authorization result must not be guessed. Bound database concurrency before an outage forces a cold-source surge.','Monitor misses separately from cache errors, and test the chosen fallback against realistic source capacity. A healthy hit ratio yesterday is not an outage plan.'],
  summary:['Outages differ from misses.','Coalescing reduces duplicate work for compatible callers.','Fallback needs bounded capacity and a correctness policy.'],check:['Six callers share one cold key. With the modeled coalescing enabled, how many source loads occur?','One, and the callers share its result. That exact grouping is a teaching assumption; a production multi-worker design needs an explicit coordination scope.'],
  controls:[['requests','Concurrent callers',1,6,4],['outage','Cache unreachable','checkbox',false],['fallback','Allow source fallback','checkbox',true],['coalesce','Share one in-flight load','checkbox',false]],presets:[['Cold stampede',{requests:4,outage:false,fallback:true,coalesce:false}],['Coalesced load',{requests:4,outage:false,fallback:true,coalesce:true}],['Reject during outage',{requests:4,outage:true,fallback:false,coalesce:false}],['Bound duplicate fallback',{requests:4,outage:true,fallback:true,coalesce:true}]],
  glossary:{Stampede:'Many duplicate source loads triggered by missing reusable data.',Fallback:'A chosen alternate behavior after a dependency problem.',Coalescing:'Sharing one in-flight operation among compatible requests.'},sources:[['Azure cache-aside availability considerations','https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside']]
 }
};
const SD_CACHE_EDGES={
 'why-caching-exists':['What should count as saved work?','Compare the same required representation and measure the operations avoided. A smaller response or rejected request is not a successful speedup of the original operation. Include lookup overhead, refresh work, and the source’s outage capacity when assessing reuse.'],
 'browser-caching':['Does an ETag reveal the body contents?','An ETag is opaque to the client. It can be computed from content or generated another way, but the client should compare and send it under the protocol rather than infer semantics from its spelling. Vary and cache keys determine which stored representation is eligible for validation.'],
 'application-caching':['What happens after a worker replacement?','The replacement has no inherited process-local copy in the ordinary deployment model. Reconstructing useful values creates a cold-load burst. Do not put the only copy of an accepted business fact in a cache whose normal replacement policy discards it.'],
 'database-caching':['What does a dirty cached page mean?','A dirty page contains modifications not yet written to its table-file location. Correct database recovery coordinates logging and page persistence; evicting or flushing it is not the same as discarding a reconstructible application result. Buffer replacement must respect pins and recovery ordering.'],
 'distributed-caching':['How does a client know which node owns a key?','A clustered product has a defined routing scheme or endpoint behavior. Redis Cluster uses hash-slot ownership and redirects, with documented migration and failure rules. The single shared endpoint here intentionally hides those details rather than treating a distributed label as a complete routing implementation.'],
 'cache-aside':['What if source loading succeeds but filling fails?','The application can often still return the authoritative read while reporting or observing the failed optimization. Its policy must say so explicitly. Repeated fill failures increase source work, and a future lookup remains cold; a successful read does not establish that the cache was populated.'],
 'read-through-and-write-through':['Can another writer bypass the facade?','It can unless the architecture enforces that boundary, and its source changes can leave the facade’s copy old. A centralized interface simplifies policy only for participants using it. External writers need reliable invalidation, change propagation, or another explicit freshness mechanism.'],
 'write-behind':['What if the source rejects a deferred update?','The original caller may already have success. Retained work needs retry, quarantine, or reconciliation, and a way to expose that the backing value is not converging. A pending queue is not useful durability if the accepted item can be silently discarded after a later validation error.'],
 'ttl':['Should failed lookups be cached too?','Negative caching can reduce repeated loads for an absent key, but a long negative lifetime can hide a newly created value. The meaning of not found, upstream failure, and denied access must remain distinct. This lab stores successful copies only and does not treat every error as a reusable absence.'],
 'cache-eviction-strategies':['Why might admission matter more than the victim rule?','A one-time scan can flood the cache with values unlikely to be reused. An admission policy can decide not to retain some fetched values instead of evicting the useful working set for every miss. The exact policies here always admit and make that simplification explicit.'],
 'cache-invalidation':['Why is a single token check insufficient?','A writer can race after the check and before publication. A safe generation design must coordinate the check, conditional fill, writer update, and reader behavior under its stated failure assumptions. The guard in this diagram is a logical protocol boundary, not an unprotected comparison followed by an ordinary SET.'],
 'cache-consistency':['Can an old source replica refill a new cache entry?','Yes, a fill can obtain an older value even after removing the previous copy. A freshness guarantee must cover the source-read path and its replica position as well as the cache. Renewing the lifetime of that old value does not make it the latest authoritative version.'],
 'redis-fundamentals':['Does ordinary SET preserve an existing TTL?','An ordinary overwriting SET removes the previous expiry unless the command specifies an expiry or uses an appropriate option such as KEEPTTL. INCR preserves it. The distinction matters when updating cached counters or representations, and should be checked against the exact command used.'],
 'cache-failure-scenarios':['What if the shared load itself fails?','All coalesced callers need a defined failure outcome, bounded waiting, and cleanup of the in-flight entry. Otherwise a stuck loader can block future requests indefinitely. Coalescing removes duplicate work; it does not make the chosen source load infallible.']
};
const SD_CACHE_PREDICTIONS={
 'why-caching-exists':[['Every repeated request loads the source','Later eligible hits avoid source reads'],1],
 'browser-caching':[['no-cache allows storage with validation','no-cache forbids all storage'],0],
 'application-caching':[['A’s removal clears every worker','B keeps its independent local copy'],1],
 'database-caching':[['Only the first SELECT executes','Every SELECT executes; page reads can decrease'],1],
 'distributed-caching':[['Shared reuse can return the same older value','Shared storage always means latest-source reads'],0],
 'cache-aside':[['The application loads an ordinary cache-aside miss','The cache autonomously queries the database'],0],
 'read-through-and-write-through':[['Memory acceptance alone is enough','This facade also waits for backing persistence'],1],
 'write-behind':[['Flushing cannot recreate lost queued work','An empty queue reconstructs the accepted update'],0],
 'ttl':[['TTL-valid may still be source-stale','A positive TTL proves the latest version'],0],
 'cache-eviction-strategies':[['FIFO keeps original insertion age','FIFO updates insertion age on every read'],0],
 'cache-invalidation':[['Deletion cancels every earlier source load','An earlier reader can fill after deletion'],1],
 'cache-consistency':[['Later refresh changes future observations','Later refresh rewrites already-returned responses'],0],
 'redis-fundamentals':[['INCR preserves the existing expiry','INCR renews the key’s TTL automatically'],0],
 'cache-failure-scenarios':[['One source load serves the modeled group','Coalescing still sends six independent loads'],0]
};
for(const [slug,c] of Object.entries(SD_CACHE_CONTENT)){
 const id='s4-'+slug;SD_LESSONS[id]={...c,deep:[...c.deep,SD_CACHE_EDGES[slug][1]],objectives:[c.summary[0],c.summary[1]],experiment:c.caption};
 const prediction=SD_CACHE_PREDICTIONS[slug];
 SD_LABS[id]={...c,challenge:c.check[0],prediction:[c.check[0],prediction[0],prediction[1],c.check[1]],discoveries:[],nodes:{
 client:['Caller observation','The caller sees the returned representation at a particular time. A cache entry’s eligibility, the source version, and a completed response are different facts; later refresh does not rewrite the earlier observation.'],
 app:['Application policy','This actor owns the read or write policy shown in the trace. It chooses loading, invalidation, fallback, or acknowledgement under this lesson’s rules; the cache box does not automatically provide those guarantees.'],
 cache:['Reusable copy boundary','The ledger exposes the retained value, lifetime, and policy state. A copy can be TTL-valid yet older than the source; expiry, eviction, persistence, and copy consistency describe distinct behaviors.'],
 db:['Authoritative source','This actor owns the backing fact, or represents the storage path for the page-buffer lesson. Its operation count is separate from cache lookup count, and source writes do not automatically modify independent copies.'],
 worker:['Another application worker','This worker can have an independent local value or access the shared entry. Removing a copy known to another worker does not automatically clear this worker’s private memory.'],
 loader:['Configured miss loader','The read-through facade invokes this code to fetch an absent value. Loading responsibility is explicit; an ordinary Redis GET does not autonomously read an application database.'],
 queue:['Accepted pending updates','Early-acknowledged work remains unapplied until flush. Whether it survives a process crash is a stated model assumption; a real queue needs documented durability, ordering, and replay guarantees.']}};
}
